"""Output manager. Writes generated bytes plus a sidecar JSON record.

The sidecar is the seed of the asset catalog: it captures exactly how each
asset was made (prompt, backend, model, size, cost, references) so the database
catalog in WS1 can ingest the same fields later. Generated files live under
brand-kits/<slug>/generated/<asset>/ and are gitignored.
"""
from __future__ import annotations

import json
from datetime import datetime
from pathlib import Path

from .backends.base import GenResult
from .brand_loader import current_kits_dir
from .compliance.lifecycle import stamp_compliance
from .prompt_builder import BuiltPrompt

_EXT = {
    "image/png": ".png",
    "image/svg+xml": ".svg",
    "image/jpeg": ".jpg",
    "image/webp": ".webp",
}


def ext_for(mime: str) -> str:
    return _EXT.get(mime, ".bin")


def generated_dir(brand_slug: str, asset_type: str, kits_dir: Path | None = None) -> Path:
    root = kits_dir or current_kits_dir()
    return root / brand_slug / "generated" / asset_type


def output_name(asset_type: str, variant: str | None, mime: str, timestamp: str) -> str:
    suffix = f"-{variant}" if variant else ""
    return f"{timestamp}-{asset_type}{suffix}{ext_for(mime)}"


def save_result(
    brand_slug: str,
    asset_type: str,
    variant: str | None,
    built: BuiltPrompt,
    result: GenResult,
    kits_dir: Path | None = None,
    now: datetime | None = None,
) -> list[Path]:
    out_dir = generated_dir(brand_slug, asset_type, kits_dir)
    out_dir.mkdir(parents=True, exist_ok=True)
    timestamp = (now or datetime.now()).strftime("%Y-%m-%d-%H-%M-%S")

    paths: list[Path] = []
    multi = len(result.images) > 1
    for i, image in enumerate(result.images):
        name = output_name(asset_type, variant, result.mime, timestamp)
        if multi:
            stem = Path(name)
            name = f"{stem.stem}-{i + 1}{stem.suffix}"
        path = out_dir / name
        path.write_bytes(image)

        record = {
            "brand": brand_slug,
            "asset_type": asset_type,
            "variant": variant,
            "backend": result.backend,
            "model": result.model,
            "mime": result.mime,
            "size": list(built.size),
            "transparent": built.transparent,
            "cost_cents": result.cost_cents,
            "prompt": built.text,
            "reference_images": [str(r) for r in built.reference_images],
            "created_at": timestamp,
            "meta": result.meta,
        }
        path.with_suffix(path.suffix + ".json").write_text(json.dumps(record, indent=2))
        # Gate the asset at creation time: stamp its lifecycle status into the
        # sidecar from the deterministic compliance verdict. Best-effort — a
        # stamping failure must never fail the generation that just succeeded.
        try:
            stamp_compliance(brand_slug, asset_type, path.name, "generated", kits_dir)
        except Exception:  # noqa: BLE001 - stamping is advisory, never fatal
            pass
        paths.append(path)
    return paths
